using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — demonstrates required EF Core 9 fixes
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Preserve legacy discriminator property name.
        // EF Core 9 changed the default from "Discriminator" to "$type".
        // Existing documents use "Discriminator", so we must explicitly configure it.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: Preserve legacy compound id format.
        // EF Core 9 no longer prepends the discriminator to the JSON id.
        // Existing documents have ids like "Session|abc123" — keep that format.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }

    // Fix 3: Sync I/O is no longer supported on the Cosmos DB provider.
    // All queries and SaveChanges calls must use async equivalents.
    //
    // BEFORE (throws in EF Core 9):
    //   var sessions = db.Sessions.ToList();
    //   db.SaveChanges();
    //
    // AFTER:
    //   var sessions = await db.Sessions.ToListAsync();
    //   await db.SaveChangesAsync();
}

class Session
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

